from functools import lru_cache

def count_up_to(n: int, k: int) -> int:
    if n <= 0:
        return 0
    s = str(n)
    L = len(s)

    @lru_cache(maxsize=None)
    def f(pos, tight, started, diff, rem):
        if pos == L:
            return 1 if (started and diff == 0 and rem == 0) else 0
        limit = int(s[pos]) if tight else 9
        total = 0
        for d in range(0, limit + 1):
            ntight = tight and (d == limit)
            if not started and d == 0:
                total += f(pos + 1, ntight, False, diff, rem)
            else:
                ndiff = diff + (1 if d % 2 == 0 else -1)
                total += f(pos + 1, ntight, True, ndiff, (rem * 10 + d) % k)
        return total

    return f(0, True, False, 0, 0)

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    return count_up_to(high, k) - count_up_to(low - 1, k)

