MOD = 998244353

def count_strongly_connected_partitions(n: int, s: str) -> int:
    m = 2 * n
    d = 0
    dp = {0: 1}  # u unmatched B's; v unmatched W's = u - d
    for idx in range(m):
        c = s[idx]
        ndp = {}
        for u, val in dp.items():
            val %= MOD
            v = u - d
            if c == 'B':
                # leave new B unmatched
                ndp[u + 1] = (ndp.get(u + 1, 0) + val) % MOD
                # match new B with an unmatched W (forward pair)
                if v > 0:
                    ndp[u] = (ndp.get(u, 0) + val * v) % MOD
            else:
                # leave new W unmatched
                ndp[u] = (ndp.get(u, 0) + val) % MOD
                # match new W with an unmatched B (backward pair)
                if u > 0:
                    ndp[u - 1] = (ndp.get(u - 1, 0) + val * u) % MOD
        d += 1 if c == 'B' else -1
        dp = ndp
        if idx < m - 1 and d <= 0:
            # every cut i with #B <= #W in prefix needs a backward-crossing pair
            if 0 in dp:
                del dp[0]
    return dp.get(0, 0) % MOD

