from typing import List
from collections import defaultdict


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    # dp[(parity, s)] = set of achievable products (0 <= p <= limit)
    # parity = length of subsequence mod 2, s = alternating sum so far
    dp = {}
    over = set()  # (parity, s) reachable with product > limit

    for x in nums:
        new_dp = defaultdict(set)
        for key, prods in dp.items():
            new_dp[key] |= prods
        new_over = set(over)

        # start a new subsequence with x
        if x == 0:
            new_dp[(1, 0)].add(0)
        elif x <= limit:
            new_dp[(1, x)].add(x)
        else:
            new_over.add((1, x))

        # extend existing subsequences
        for (par, s), prods in dp.items():
            sign = 1 if par == 0 else -1
            key = (1 - par, s + sign * x)
            if x == 0:
                new_dp[key].add(0)
            else:
                for p in prods:
                    np_ = p * x
                    if np_ <= limit:
                        new_dp[key].add(np_)
                    else:
                        new_over.add(key)

        # extend over-limit subsequences (product value irrelevant;
        # only a zero can bring the product back to <= limit)
        for (par, s) in over:
            sign = 1 if par == 0 else -1
            key = (1 - par, s + sign * x)
            if x == 0:
                new_dp[key].add(0)
            else:
                new_over.add(key)

        dp = dict(new_dp)
        over = new_over

    best = -1
    for (par, s), prods in dp.items():
        if s == k:
            for p in prods:
                if p > best:
                    best = p
    return best

