from typing import List
from math import factorial


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    odds = list(range(1, n + 1, 2))
    evens = list(range(2, n + 1, 2))
    fact = {i: factorial(i) for i in range(n + 1)}

    def completions(o: int, e: int, next_parity: int) -> int:
        # number of ways to fill remaining o odds / e evens alternating
        # starting with parity next_parity (0 odd, 1 even)
        L = o + e
        if L == 0:
            return 1
        cnt_next = (L + 1) // 2  # slots matching next_parity
        cnt_oth = L // 2
        c_o, c_e = (o, e) if next_parity == 1 else (e, o)
        if c_o == cnt_next and c_e == cnt_oth:
            return fact[o] * fact[e]
        return 0

    # total count
    total = completions(len(odds), len(evens), 0) + completions(len(odds), len(evens), 1)
    if k > total:
        return []

    res = []
    prev_parity = None
    for _ in range(n):
        if prev_parity is None:
            cand_parity = None
        else:
            cand_parity = 1 - prev_parity
        pool = odds + evens
        if cand_parity is not None:
            pool = [v for v in pool if v % 2 == cand_parity]
        pool.sort()
        placed = False
        for v in pool:
            o_after = len(odds) - (1 if v % 2 == 1 else 0)
            e_after = len(evens) - (1 if v % 2 == 0 else 0)
            cnt = completions(o_after, e_after, 1 - v % 2)
            if k <= cnt:
                res.append(v)
                if v % 2 == 1:
                    odds.remove(v)
                else:
                    evens.remove(v)
                prev_parity = v % 2
                placed = True
                break
            else:
                k -= cnt
        if not placed:
            return []
    return res

