def min_operations_to_rearrange(n, s, t):
    if s.count('B') != t.count('B'):
        return -1
    m = n + 2
    # empty pair is always adjacent; e = start index of empty pair (0..m-2)
    moves = [[i for i in range(m - 1) if i not in (e - 1, e, e + 1)]
             for e in range(m - 1)]
    start = (m - 2, s + '..')
    goal = (m - 2, t + '..')
    if start == goal:
        return 0

    distS = {start: 0}
    distT = {goal: 0}
    fS = {start}
    fT = {goal}

    def expand(front, dist, other):
        new = set()
        ans = None
        for e, cfg in front:
            cells = list(cfg)
            d = dist[(e, cfg)]
            for i in moves[e]:
                nb = cells[:]
                nb[e], nb[e + 1] = cells[i], cells[i + 1]
                nb[i] = nb[i + 1] = '.'
                key = (i, ''.join(nb))
                if key in other:
                    return None, d + 1 + other[key]
                if key not in dist:
                    dist[key] = d + 1
                    new.add(key)
        return new, ans

    while fS and fT:
        if len(fS) <= len(fT):
            fS, r = expand(fS, distS, distT)
        else:
            fT, r = expand(fT, distT, distS)
        if r is not None:
            return r
    return -1

