"""Find a palindrome expression (digits 1-9 and '*') evaluating to n.

Structure of any valid palindrome expression:
Its tokens (numbers separated by '*') mirror: token i equals the digit
reverse of token (k+1-i).  Hence the value is always
    n = c * prod(a_j * reverse(a_j))
where c is a zero-free palindromic number (the middle token) and a_j are
arbitrary zero-free numbers.  We search over palindromic divisors c of n
and try to peel off factors of the form a * reverse(a) recursively.
"""

import sys

sys.setrecursionlimit(100000)


def _rev(x: int) -> int:
    return int(str(x)[::-1])


def _zero_free_palindrome(x: int) -> bool:
    s = str(x)
    return s == s[::-1] and '0' not in s


def _divisors(n: int):
    ds = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)


class _PairSearch:
    """Decide whether m can be written as prod(a_j * reverse(a_j))."""

    def __init__(self, node_limit=2000000):
        self.memo = {}
        self.divcache = {}
        self.nodes = 0
        self.node_limit = node_limit

    def search(self, m):
        if m == 1:
            return []
        if m in self.memo:
            return self.memo[m]
        self.nodes += 1
        if self.nodes > self.node_limit:
            raise RuntimeError('search limit exceeded')
        self.memo[m] = None  # cycle guard
        if m not in self.divcache:
            self.divcache[m] = _divisors(m)
        for d in self.divcache[m]:
            if d < 2 or '0' in str(d):
                continue
            p = d * _rev(d)
            if m % p == 0:
                rest = self.search(m // p)
                if rest is not None:
                    res = [d] + rest
                    self.memo[m] = res
                    return res
        return None


def find_palindrome_expression(n: int) -> str:
    if not isinstance(n, int) or n < 1 or n > 10 ** 12:
        return '-1'

    # Single token: n itself must be a zero-free palindrome.
    if _zero_free_palindrome(n):
        return str(n)

    searcher = _PairSearch()
    for c in _divisors(n):
        if not _zero_free_palindrome(c):
            continue
        m = n // c
        try:
            lst = searcher.search(m)
        except RuntimeError:
            return '-1'
        if lst is not None and not (c == 1 and not lst):
            tokens = lst + [c] + [_rev(x) for x in reversed(lst)]
            return '*'.join(str(t) for t in tokens)
    return '-1'

