MOD = 10**9 + 7

def count_good_arrays(n: int, m: int, k: int) -> int:
    if k < 0 or k > n - 1:
        return 0
    # C(n-1, k) * m * (m-1)^(n-1-k)
    def comb(a, b):
        if b < 0 or b > a:
            return 0
        b = min(b, a - b)
        num = 1
        den = 1
        for i in range(b):
            num = num * (a - i) % MOD
            den = den * (i + 1) % MOD
        return num * pow(den, MOD - 2, MOD) % MOD
    return comb(n - 1, k) * m % MOD * pow(m - 1, n - 1 - k, MOD) % MOD if m > 1 else (comb(n - 1, k) * m % MOD if k == n - 1 or (n == 1) else 0)

