def _distinct_prime_count(m):
    cnt = 0
    d = 2
    while d * d <= m:
        if m % d == 0:
            cnt += 1
            if cnt > 2:
                return cnt
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        cnt += 1
    return cnt

def find_largest_400_number(a: int) -> int:
    m = math.isqrt(a)
    while _distinct_prime_count(m) != 2:
        m -= 1
    return m * m

