# required exponents of (2,3,5,7) for each digit sum 1..81, or None if not 7-smooth
def _factor_req(s):
    exps = []
    for p in (2,3,5,7):
        e = 0
        while s % p == 0:
            s //= p; e += 1
        exps.append(e)
    if s != 1:
        return None
    return tuple(exps)

REQ = [None] + [ _factor_req(s) for s in range(1, 82) ]
CAPS = (6, 4, 2, 2)

# digit -> exponent increments
INC = []
for dg in range(10):
    inc = []
    for i, p in enumerate((2,3,5,7)):
        e = 0
        while dg and dg % p == 0:
            dg //= p; e += 1
        inc.append(e)
    INC.append(tuple(inc))
INC[0] = None  # zero handled specially

@lru_cache(maxsize=None)
def dp(k, started, s, a, b, c, d, zero):
    if k == 0:
        if not started:
            return 0
        if zero:
            return 1
        req = REQ[s]
        if req is None:
            return 0
        return int(a >= req[0] and b >= req[1] and c >= req[2] and d >= req[3])
    total = 0
    for dg in range(10):
        if not started and dg == 0:
            total += dp(k-1, False, 0, 0, 0, 0, 0, False)
        elif dg == 0:
            total += dp(k-1, True, s, 0, 0, 0, 0, True)
        else:
            inc = INC[dg]
            na = min(a + inc[0], CAPS[0]); nb = min(b + inc[1], CAPS[1])
            nc = min(c + inc[2], CAPS[2]); nd = min(d + inc[3], CAPS[3])
            total += dp(k-1, True, s + dg, na, nb, nc, nd, zero)
    return total

def f(n):
    if n <= 0:
        return 0
    ds = [int(ch) for ch in str(n)]
    k = len(ds)
    total = 0
    started = False; s = 0; a=b=c=d=0; zero=False
    for i, lim in enumerate(ds):
        rem = k - i - 1
        for dg in range(lim):
            if not started and dg == 0:
                total += dp(rem, False, 0, 0, 0, 0, 0, False)
            elif dg == 0:
                total += dp(rem, True, s, 0, 0, 0, 0, True)
            else:
                inc = INC[dg]
                total += dp(rem, True, s + dg,
                            min(a+inc[0], CAPS[0]), min(b+inc[1], CAPS[1]),
                            min(c+inc[2], CAPS[2]), min(d+inc[3], CAPS[3]), zero)
        # continue tight with digit == lim
        if not started and lim == 0:
            continue  # still not started
        started = True
        if lim == 0:
            zero = True; a=b=c=d=0
        else:
            s += lim
            inc = INC[lim]
            a=min(a+inc[0],6); b=min(b+inc[1],4); c=min(c+inc[2],2); d=min(d+inc[3],2)
    # final tight number n itself
    if started:
        if zero:
            total += 1
        else:
            req = REQ[s]
            if req and a>=req[0] and b>=req[1] and c>=req[2] and d>=req[3]:
                total += 1
    return total

