def _cost(t: str) -> int:
    n = len(t)
    best = None
    for d in range(1, n):
        if n % d:
            continue
        c = 0
        for r in range(d):
            idxs = list(range(r, n, d))
            i, j = 0, len(idxs) - 1
            while i < j:
                if t[idxs[i]] != t[idxs[j]]:
                    c += 1
                i += 1
                j -= 1
        if best is None or c < best:
            best = c
    return best if best is not None else 0

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    INF = float('inf')
    # cost[i][j]: cost of s[i:j+1]
    cost = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            cost[i][j] = _cost(s[i:j+1])
    # dp
    dp = [[INF]*(k+1) for _ in range(n+1)]
    dp[0][0] = 0
    for i in range(1, n+1):
        for j in range(1, k+1):
            for p in range(i-1):
                if dp[p][j-1] < INF and (i-p) >= 2:
                    v = dp[p][j-1] + cost[p][i-1]
                    if v < dp[i][j]:
                        dp[i][j] = v
    return dp[n][k]

