    return res if res else '0'

def _count_up_to(n: str) -> int:
    """Stepping numbers in [1, n], mod MOD. n >= 0."""
    L = len(n)
    total = 0
    # full lengths < L
    for _length in range(1, L):
        prev_counts = [0] * 10
        for d in range(1, 10):
            prev_counts[d] = 1
        for _ in range(_length - 1):
            new = [0] * 10
            for d in range(10):
                for p in (d - 1, d + 1):
                    if 0 <= p < 10:
                        new[d] = (new[d] + prev_counts[p]) % MOD
            prev_counts = new
        total = (total + sum(prev_counts)) % MOD

    # tight count for exactly length L
    from functools import lru_cache
    ndigits = [int(c) for c in n]

    @lru_cache(None)
    def rec(i, prev, tight):
        if i == L:
            return 1
        limit = ndigits[i] if tight else 9
        lo = 1 if i == 0 else 0
        s = 0
        for d in range(lo, limit + 1):
            if i > 0 and abs(d - prev) != 1:
                continue
            s = (s + rec(i + 1, d, tight and d == limit)) % MOD
        return s

    total = (total + rec(0, -1, True)) % MOD
    return total

