from typing import List


def min_operations_to_sum(nums: List[int], target: int) -> int:
    """Minimum operations (splitting a power of two into two halves) so that
    some subsequence of nums sums to target, or -1 if impossible."""
    if target <= 0:
        return 0
    if sum(nums) < target:
        return -1

    MAXB = 64
    cnt = [0] * (MAXB + 2)
    for x in nums:
        if x > 0:
            cnt[x.bit_length() - 1] += 1

    ans = 0
    for i in range(MAXB):
        if (target >> i) & 1:
            if cnt[i] == 0:
                # find nearest higher available power and split down
                j = i + 1
                while j <= MAXB and cnt[j] == 0:
                    j += 1
                if j > MAXB:
                    return -1
                while j > i:
                    cnt[j - 1] += 2
                    cnt[j] -= 1
                    ans += 1
                    j -= 1
            cnt[i] -= 1
        # carry surplus pairs upward (two 2^i can act as one 2^(i+1))
        cnt[i + 1] += cnt[i] // 2
        cnt[i] %= 2
    return ans

