from typing import List


def _count_bit(n: int, b: int) -> int:
    """Count integers in [1, n] with bit b set."""
    p = 1 << b
    return (n + 1) // (2 * p) * p + max(0, (n + 1) % (2 * p) - p)


def _L(n: int) -> int:
    """Total length of powerful arrays for 1..n."""
    if n <= 0:
        return 0
    total = 0
    b = 0
    while (1 << b) <= n:
        total += _count_bit(n, b)
        b += 1
    return total


def _F(n: int) -> int:
    """Sum of exponents over all elements of powerful arrays for 1..n."""
    if n <= 0:
        return 0
    total = 0
    b = 0
    while (1 << b) <= n:
        total += b * _count_bit(n, b)
        b += 1
    return total


def _prefix(idx: int) -> int:
    """Sum of exponents of big_nums[0..idx-1]."""
    if idx <= 0:
        return 0
    # binary search largest n with L(n) <= idx
    lo, hi = 0, 1
    while _L(hi) < idx:
        hi *= 2
    n = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if _L(mid) <= idx:
            n = mid
            lo = mid + 1
        else:
            hi = mid - 1
    total = _F(n)
    r = idx - _L(n)
    num = n + 1
    b = 0
    while r > 0:
        if num >> b & 1:
            total += b
            r -= 1
        b += 1
    return total


