def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """Backtracking over rows: pick distinct columns for A, B, C in each row."""
    used = {ch: set() for ch in 'ABC'}   # columns already occupied by each letter
    top = [None] * n                     # topmost letter in each column
    grid = [['.'] * n for _ in range(n)]

    def dfs(i: int) -> bool:
        if i == n:
            return all(top[j] == c[j] for j in range(n))
        for cols in permutations(range(n), 3):
            row = ['.'] * n
            for ch, col in zip('ABC', cols):
                row[col] = ch
            # column-letter uniqueness
            if any(col in used[ch] for ch, col in zip('ABC', cols)):
                continue
            # leftmost character in this row must match r[i]
            first = min(cols)
            if row[first] != r[i]:
                continue
            # apply
            saved_top = [(col, top[col]) for col in cols if top[col] is None]
            for col in cols:
                if top[col] is None:
                    top[col] = row[col]
            for ch, col in zip('ABC', cols):
                used[ch].add(col)
            grid[i] = row
            if dfs(i + 1):
                return True
            # undo
            for ch, col in zip('ABC', cols):
                used[ch].discard(col)
            for col, val in saved_top:
                top[col] = val
        return False

    if dfs(0):
        return [''.join(row) for row in grid]
    return None

