    pts = sorted(positions)
    p = [0] + [y for _, y in pts]  # 1-indexed by x
    N = n + 2
    # C[i][v] = # points with x<=i and y<=v
    C = [[0] * N for _ in range(n + 1)]
    for i in range(1, n + 1):
        prev = C[i - 1]; cur = C[i]; pi = p[i]
        for v in range(N):
            cur[v] = prev[v] + (1 if pi <= v else 0)

    def box_good(x1, y1, x2, y2):
        # points k with x1<k<x2, y1<p_k<y2 ; each must have comparable partner in box
        X2 = x2 - 1; Y2 = y2 - 1
        for k in range(x1 + 1, x2):
            pk = p[k]
            if not (y1 < pk < y2):
                continue
            # LL partner: m in (x1,k), p_m in (y1,pk)
            if C[k - 1][pk - 1] - C[x1][pk - 1] - C[k - 1][y1] + C[x1][y1] > 0:
                continue
            # UR partner: m in (k,x2), p_m in (pk,y2)
            if C[X2][Y2] - C[k][Y2] - C[X2][pk] + C[k][pk] > 0:
                continue
            return False
        return True

    # whole set has no isolated point?
    whole_good = True
    for k in range(1, n + 1):
        pk = p[k]
        ll = C[k - 1][pk - 1]
        ur = (n - pk) - (k - C[k][pk])
        if ll == 0 and ur == 0:
            whole_good = False
            break

    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        val = 1 if box_good(0, p[i], i, n + 1) else 0
        pi = p[i]
        for j in range(1, i):
            if p[j] > pi and dp[j] and box_good(j, pi, i, p[j]):
                val += dp[j]
        dp[i] = val % MOD

    ans = 1 if whole_good else 0
    for i in range(1, n + 1):
        if dp[i] and box_good(i, 0, n + 1, p[i]):
            ans += dp[i]
    return ans % MOD

