from typing import List
from math import gcd

def _lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def kth_smallest_amount(coins: List[int], k: int) -> int:
    coins = list(set(coins))
    n = len(coins)
    signed = []
    for mask in range(1, 1 << n):
        l = 1
        bits = 0
        m = mask
        i = 0
        while m:
            if m & 1:
                l = _lcm(l, coins[i])
                bits += 1
            m >>= 1
            i += 1
        signed.append((l, 1 if bits % 2 == 1 else -1))

    def count(x):
        return sum(sg * (x // l) for l, sg in signed)

    lo, hi = 1, k * max(coins)
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

