                    for z in zo:
                        y2=y+z
                        if 0<=y2<=1: NF|=1<<(2*a+y2)
                t[F]=NF
            trans[(c,r)]=t
    P={0b1001:1}
    for i in range(1,n):
        c=1 if s[i]=='1' else 0
        items=[(r,trans[(c,r)]) for r in rvals(c)]
        P2={}
        for F,p in P.items():
            for r,t in items:
                NF=t[F]
                if NF==0: continue
                P2[NF]=(P2.get(NF,0)+p)%MOD
        P=P2
    c0=1 if s[0]=='1' else 0
    total=0
    for F,p in P.items():
        cnt=0
        for r in rvals(c0):
            zo=[z for z in ((r,r+1) if c0 else (r,)) if -1<=z<=1]
            for (a,y) in PAIRS:
                if (F>>(2*a+y))&1 and (a-y) in zo: cnt+=1; break
