from typing import List


def min_cost_to_sort(n: int, permutation: List[int]) -> int:
    pos = {v: i for i, v in enumerate(permutation)}
    total = 0
    for z in range(1, n + 1):
        # A = number of smaller elements that start to the right of z (inversions
        # where z is the larger/left element).
        A = sum(1 for y in range(1, z) if pos[y] > pos[z])
        total += A * (2 * z - A - 1) // 2
    return total

