def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    if s.count('0') != t.count('0'):
        return False
    ps = [i for i, c in enumerate(s) if c == '1']
    pt = [i for i, c in enumerate(t) if c == '1']
    if len(ps) != len(pt):
        return False
    if any(a % x != b % x for a, b in zip(ps, pt)):
        return False
    qs = [i for i, c in enumerate(s) if c == '0']
    qt = [i for i, c in enumerate(t) if c == '0']
    if any(a % y != b % y for a, b in zip(qs, qt)):
        return False
    return True

